{
  "name": "payments-frontend",
  "private": true,
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.1",
    "vite": "^5.4.0"
  }
}

import { useEffect, useMemo, useState } from "react";
import {
  createPayment,
  failPayment,
  getPayment,
  getPaymentHistory,
  listPayments,
  transitionPayment
} from "./api";

const initialForm = {
  idempotencyKey: "",
  sourceAccount: "",
  destinationAccount: "",
  amount: "",
  currency: "USD",
  reference: ""
};

export default function App() {
  const [form, setForm] = useState(initialForm);
  const [payments, setPayments] = useState([]);
  const [selectedPayment, setSelectedPayment] = useState(null);
  const [history, setHistory] = useState([]);
  const [statusFilter, setStatusFilter] = useState("");
  const [paymentIdInput, setPaymentIdInput] = useState("");
  const [message, setMessage] = useState("Ready");
  const [messageType, setMessageType] = useState("info");
  const [failForm, setFailForm] = useState({
    errorCode: "NETWORK_ERROR",
    errorMessage: "Manual failure from frontend"
  });
  const [loading, setLoading] = useState(false);

  const canTransition = useMemo(() => {
    if (!selectedPayment) {
      return {};
    }
    return {
      validate: selectedPayment.status === "CREATED",
      send: selectedPayment.status === "VALIDATED",
      complete: selectedPayment.status === "SENT",
      fail: ["CREATED", "VALIDATED", "SENT"].includes(selectedPayment.status)
    };
  }, [selectedPayment]);

  useEffect(() => {
    void loadPayments();
  }, []);

  function setFeedback(text, type = "info") {
    setMessage(text);
    setMessageType(type);
  }

  async function withLoading(action) {
    try {
      setLoading(true);
      await action();
    } catch (error) {
      setFeedback(error.message, "error");
    } finally {
      setLoading(false);
    }
  }

  function onFormChange(event) {
    const { name, value } = event.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  }

  function parseAmount(amountValue) {
    const amount = Number.parseFloat(amountValue);
    if (Number.isNaN(amount)) {
      throw new Error("Amount must be a valid number");
    }
    return amount;
  }

  async function handleCreatePayment(event) {
    event.preventDefault();

    if (form.sourceAccount === form.destinationAccount) {
      setFeedback("Source and destination accounts must be different", "error");
      return;
    }

    await withLoading(async () => {
      const payload = { ...form, amount: parseAmount(form.amount) };
      const payment = await createPayment(payload);
      setSelectedPayment(payment);
      setPaymentIdInput(payment.id);
      setHistory(await getPaymentHistory(payment.id));
      setFeedback(`Payment saved with id ${payment.id}`, "success");
      setForm((prev) => ({ ...prev, amount: "", reference: "" }));
      const data = await listPayments(statusFilter || "");
      setPayments(data);
    });
  }

  async function loadPayments(status = statusFilter) {
    await withLoading(async () => {
      const data = await listPayments(status || "");
      setPayments(data);
      setFeedback(`Loaded ${data.length} payment(s)`, "info");
    });
  }

  async function loadPaymentById() {
    if (!paymentIdInput.trim()) {
      setFeedback("Enter a payment id first", "error");
      return;
    }

    await withLoading(async () => {
      const payment = await getPayment(paymentIdInput.trim());
      setSelectedPayment(payment);
      setHistory(await getPaymentHistory(payment.id));
      setFeedback(`Loaded payment ${payment.id}`, "success");
    });
  }

  async function doTransition(action) {
    if (!selectedPayment) {
      setFeedback("Load or create a payment first", "error");
      return;
    }

    await withLoading(async () => {
      const updated = await transitionPayment(selectedPayment.id, action);
      setSelectedPayment(updated);
      setHistory(await getPaymentHistory(updated.id));
      setFeedback(`Payment moved to ${updated.status}`, "success");
      const data = await listPayments(statusFilter || "");
      setPayments(data);
    });
  }

  async function doFail() {
    if (!selectedPayment) {
      setFeedback("Load or create a payment first", "error");
      return;
    }
    if (!canTransition.fail) {
      setFeedback("Current status cannot transition to FAILED", "error");
      return;
    }

    await withLoading(async () => {
      const updated = await failPayment(selectedPayment.id, failForm);
      setSelectedPayment(updated);
      setHistory(await getPaymentHistory(updated.id));
      setFeedback(`Payment moved to ${updated.status}`, "success");
      const data = await listPayments(statusFilter || "");
      setPayments(data);
    });
  }

  return (
    <main className="app">
      <h1>Payments Frontend (React)</h1>
      <p className="hint">Backend API: http://localhost:8080/api/payments</p>

      <section className="card">
        <h2>Create Payment</h2>
        <form className="grid" onSubmit={handleCreatePayment}>
          <input name="idempotencyKey" placeholder="Idempotency Key" value={form.idempotencyKey} onChange={onFormChange} required />
          <input name="sourceAccount" placeholder="Source Account (8-20 digits)" value={form.sourceAccount} onChange={onFormChange} pattern="[0-9]{8,20}" title="Source account must be 8-20 digits" required />
          <input name="destinationAccount" placeholder="Destination Account (8-20 digits)" value={form.destinationAccount} onChange={onFormChange} pattern="[0-9]{8,20}" title="Destination account must be 8-20 digits" required />
          <input name="amount" type="number" min="0.01" max="1000000" step="0.01" placeholder="Amount" value={form.amount} onChange={onFormChange} required />
          <select name="currency" value={form.currency} onChange={onFormChange}>
            <option value="USD">USD</option>
            <option value="EUR">EUR</option>
            <option value="GBP">GBP</option>
          </select>
          <input name="reference" placeholder="Reference (optional)" value={form.reference} onChange={onFormChange} />
          <button disabled={loading} type="submit">{loading ? "Creating..." : "Create"}</button>
        </form>
      </section>

      <section className="card">
        <h2>Query Payment</h2>
        <div className="row">
          <input placeholder="Payment ID" value={paymentIdInput} onChange={(e) => setPaymentIdInput(e.target.value)} />
          <button disabled={loading} onClick={loadPaymentById}>Load by ID</button>
        </div>
      </section>

      <section className="card">
        <h2>Payment List</h2>
        <div className="row">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option value="">All Statuses</option>
            <option value="CREATED">CREATED</option>
            <option value="VALIDATED">VALIDATED</option>
            <option value="SENT">SENT</option>
            <option value="COMPLETED">COMPLETED</option>
            <option value="FAILED">FAILED</option>
          </select>
          <button disabled={loading} onClick={() => loadPayments(statusFilter)}>Refresh List</button>
        </div>
        <div className="list">
          {payments.map((payment) => (
            <button key={payment.id} className="list-item" onClick={() => { setSelectedPayment(payment); setPaymentIdInput(payment.id); }}>
              <strong>{payment.id}</strong> | {payment.amount} {payment.currency} | {payment.status}
            </button>
          ))}
        </div>
      </section>

      <section className="card">
        <h2>Selected Payment</h2>
        {selectedPayment ? (
          <>
            <pre>{JSON.stringify(selectedPayment, null, 2)}</pre>
            <div className="row">
              <button disabled={loading || !canTransition.validate} onClick={() => doTransition("validate")}>Validate</button>
              <button disabled={loading || !canTransition.send} onClick={() => doTransition("send")}>Send</button>
              <button disabled={loading || !canTransition.complete} onClick={() => doTransition("complete")}>Complete</button>
              <button className="danger" disabled={loading || !canTransition.fail} onClick={doFail}>Fail</button>
            </div>
            <div className="grid fail-grid">
              <input
                value={failForm.errorCode}
                onChange={(e) => setFailForm((prev) => ({ ...prev, errorCode: e.target.value }))}
                placeholder="Error Code"
              />
              <input
                value={failForm.errorMessage}
                onChange={(e) => setFailForm((prev) => ({ ...prev, errorMessage: e.target.value }))}
                placeholder="Error Message"
              />
            </div>
          </>
        ) : (
          <p>No payment selected</p>
        )}
      </section>

      <section className="card">
        <h2>Status History</h2>
        {history.length === 0 ? <p>No history</p> : <pre>{JSON.stringify(history, null, 2)}</pre>}
      </section>

      <p className={`message ${messageType}`}>{loading ? "Loading..." : message}</p>
    </main>
  );
}

const API_BASE_URL = "http://localhost:8080/api/payments";

function parseErrorMessage(rawText, status) {
  if (!rawText) {
    return `Request failed with status ${status}`;
  }

  try {
    const parsed = JSON.parse(rawText);
    if (parsed.message && parsed.errorCode) {
      return `${parsed.errorCode}: ${parsed.message}`;
    }
    return parsed.message || rawText;
  } catch {
    return rawText;
  }
}

async function request(path = "", options = {}) {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...(options.headers || {})
    },
    ...options
  });

  if (!response.ok) {
    const text = await response.text();
    throw new Error(parseErrorMessage(text, response.status));
  }

  return response.json();
}

export function createPayment(payload) {
  return request("", {
    method: "POST",
    body: JSON.stringify(payload)
  });
}

export function listPayments(status) {
  const query = status ? `?status=${encodeURIComponent(status)}` : "";
  return request(query);
}

export function getPayment(paymentId) {
  return request(`/${paymentId}`);
}

export function getPaymentHistory(paymentId) {
  return request(`/${paymentId}/history`);
}

export function transitionPayment(paymentId, action) {
  return request(`/${paymentId}/${action}`, { method: "POST" });
}

export function failPayment(paymentId, payload) {
  return request(`/${paymentId}/fail`, {
    method: "POST",
    body: JSON.stringify(payload)
  });
}

import React from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import "./styles.css";

ReactDOM.createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

:root {
  font-family: Arial, sans-serif;
  color: #1f2937;
  background: #f3f4f6;
}

body {
  margin: 0;
}

.app {
  max-width: 1000px;
  margin: 0 auto;
  padding: 20px;
}

.hint {
  margin-top: -8px;
  color: #6b7280;
}

.card {
  background: white;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 12px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
}

.grid {
  display: grid;
  gap: 8px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.fail-grid {
  margin-top: 8px;
}

input,
select,
button {
  padding: 8px;
  border: 1px solid #d1d5db;
  border-radius: 6px;
}

button {
  cursor: pointer;
  background: #2563eb;
  color: white;
}

button.danger {
  background: #dc2626;
}

button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.list {
  margin-top: 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.list-item {
  text-align: left;
  background: #f9fafb;
  color: #111827;
}

pre {
  background: #111827;
  color: #f9fafb;
  padding: 12px;
  border-radius: 6px;
  overflow: auto;
}

.message {
  font-weight: bold;
}

.message.info {
  color: #1f2937;
}

.message.success {
  color: #166534;
}

.message.error {
  color: #b91c1c;
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  server: {
    port: 5173
  }
});

package org.example;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class PaymentApplication {
    public static void main(String[] args) {
        SpringApplication.run(PaymentApplication.class, args);
    }
}

package org.example.payment.controller;

import jakarta.validation.Valid;
import org.example.payment.dto.CreatePaymentRequest;
import org.example.payment.dto.FailPaymentRequest;
import org.example.payment.dto.PaymentHistoryResponse;
import org.example.payment.dto.PaymentResponse;
import org.example.payment.model.Payment;
import org.example.payment.model.PaymentStatus;
import org.example.payment.model.PaymentStatusHistory;
import org.example.payment.service.PaymentService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.CrossOrigin;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@RestController
@RequestMapping("/api/payments")
@CrossOrigin(origins = {"http://localhost:5173", "http://127.0.0.1:5173"})
public class PaymentController {

    private final PaymentService paymentService;

    public PaymentController(PaymentService paymentService) {
        this.paymentService = paymentService;
    }

    @PostMapping
    public ResponseEntity<PaymentResponse> create(@Valid @RequestBody CreatePaymentRequest request) {
        PaymentService.CreatePaymentResult result = paymentService.createPayment(request);
        HttpStatus status = result.created() ? HttpStatus.CREATED : HttpStatus.OK;
        return ResponseEntity.status(status).body(toResponse(result.payment()));
    }

    @GetMapping("/{paymentId}")
    public PaymentResponse getById(@PathVariable String paymentId) {
        return toResponse(paymentService.getPayment(paymentId));
    }

    @GetMapping
    public List<PaymentResponse> list(@RequestParam(required = false) PaymentStatus status) {
        return paymentService.listPayments(status).stream().map(this::toResponse).toList();
    }

    @GetMapping("/{paymentId}/history")
    public List<PaymentHistoryResponse> history(@PathVariable String paymentId) {
        return paymentService.getHistory(paymentId).stream().map(this::toHistoryResponse).toList();
    }

    @PostMapping("/{paymentId}/validate")
    public PaymentResponse validate(@PathVariable String paymentId) {
        return toResponse(paymentService.validate(paymentId));
    }

    @PostMapping("/{paymentId}/send")
    public PaymentResponse send(@PathVariable String paymentId) {
        return toResponse(paymentService.send(paymentId));
    }

    @PostMapping("/{paymentId}/complete")
    public PaymentResponse complete(@PathVariable String paymentId) {
        return toResponse(paymentService.complete(paymentId));
    }

    @PostMapping("/{paymentId}/fail")
    public PaymentResponse fail(@PathVariable String paymentId, @Valid @RequestBody FailPaymentRequest request) {
        return toResponse(paymentService.fail(paymentId, request));
    }

    private PaymentResponse toResponse(Payment payment) {
        return new PaymentResponse(
                payment.getId(),
                payment.getIdempotencyKey(),
                payment.getSourceAccount(),
                payment.getDestinationAccount(),
                payment.getAmount(),
                payment.getCurrency(),
                payment.getReference(),
                payment.getStatus(),
                payment.getErrorCode(),
                payment.getErrorMessage(),
                payment.getCreatedAt(),
                payment.getUpdatedAt()
        );
    }

    private PaymentHistoryResponse toHistoryResponse(PaymentStatusHistory history) {
        return new PaymentHistoryResponse(
                history.getId(),
                history.getPaymentId(),
                history.getFromStatus(),
                history.getToStatus(),
                history.getErrorCode(),
                history.getErrorMessage(),
                history.getTriggeredBy(),
                history.getChangedAt()
        );
    }
}

package org.example.payment.dto;

import jakarta.validation.constraints.DecimalMax;
import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.math.BigDecimal;

public record CreatePaymentRequest(
        @NotBlank(message = "idempotencyKey is required")
        @Size(max = 64, message = "idempotencyKey max length is 64")
        String idempotencyKey,

        @NotBlank(message = "sourceAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "sourceAccount must be 8-20 digits")
        String sourceAccount,

        @NotBlank(message = "destinationAccount is required")
        @Pattern(regexp = "^[0-9]{8,20}$", message = "destinationAccount must be 8-20 digits")
        String destinationAccount,

        @DecimalMin(value = "0.01", message = "amount must be greater than 0")
        @DecimalMax(value = "1000000.00", message = "amount must not exceed 1,000,000")
        @Digits(integer = 12, fraction = 2, message = "amount must have up to 2 decimal places")
        BigDecimal amount,

        @NotBlank(message = "currency is required")
        @Pattern(regexp = "^[A-Z]{3}$", message = "currency must be ISO-4217 format (e.g. USD)")
        String currency,

        @Size(max = 140, message = "reference max length is 140")
        String reference
) {
}

package org.example.payment.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

public record FailPaymentRequest(
        @NotBlank(message = "errorCode is required")
        @Size(max = 64, message = "errorCode max length is 64")
        String errorCode,

        @NotBlank(message = "errorMessage is required")
        @Size(max = 255, message = "errorMessage max length is 255")
        String errorMessage
) {
}

package org.example.payment.dto;

import org.example.payment.model.PaymentStatus;

import java.time.LocalDateTime;

public record PaymentHistoryResponse(
        Long id,
        String paymentId,
        PaymentStatus fromStatus,
        PaymentStatus toStatus,
        String errorCode,
        String errorMessage,
        String triggeredBy,
        LocalDateTime changedAt
) {
}

package org.example.payment.dto;

import org.example.payment.model.PaymentStatus;

import java.math.BigDecimal;
import java.time.LocalDateTime;

public record PaymentResponse(
        String id,
        String idempotencyKey,
        String sourceAccount,
        String destinationAccount,
        BigDecimal amount,
        String currency,
        String reference,
        PaymentStatus status,
        String errorCode,
        String errorMessage,
        LocalDateTime createdAt,
        LocalDateTime updatedAt
) {
}

package org.example.payment.exception;

import java.time.LocalDateTime;

public record ApiErrorResponse(
        String errorCode,
        String message,
        LocalDateTime timestamp
) {
}

package org.example.payment.exception;

public class BusinessException extends RuntimeException {
    private final ErrorCode errorCode;

    public BusinessException(ErrorCode errorCode, String message) {
        super(message);
        this.errorCode = errorCode;
    }

    public ErrorCode getErrorCode() {
        return errorCode;
    }
}

package org.example.payment.exception;

import org.springframework.http.HttpStatus;

public enum ErrorCode {
    VALIDATION_FAILED(HttpStatus.BAD_REQUEST),
    INSUFFICIENT_FUNDS(HttpStatus.BAD_REQUEST),
    INVALID_ACCOUNT(HttpStatus.BAD_REQUEST),
    INVALID_CURRENCY(HttpStatus.BAD_REQUEST),
    INVALID_AMOUNT(HttpStatus.BAD_REQUEST),
    DUPLICATE_PAYMENT(HttpStatus.CONFLICT),
    INVALID_STATUS_TRANSITION(HttpStatus.BAD_REQUEST),
    PAYMENT_NOT_FOUND(HttpStatus.NOT_FOUND),
    PROCESSING_ERROR(HttpStatus.INTERNAL_SERVER_ERROR),
    NETWORK_ERROR(HttpStatus.SERVICE_UNAVAILABLE);

    private final HttpStatus httpStatus;

    ErrorCode(HttpStatus httpStatus) {
        this.httpStatus = httpStatus;
    }

    public HttpStatus getHttpStatus() {
        return httpStatus;
    }
}

package org.example.payment.exception;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.time.LocalDateTime;
import java.util.stream.Collectors;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(BusinessException.class)
    public ResponseEntity<ApiErrorResponse> handleBusiness(BusinessException ex) {
        return ResponseEntity.status(ex.getErrorCode().getHttpStatus())
                .body(new ApiErrorResponse(ex.getErrorCode().name(), ex.getMessage(), LocalDateTime.now()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ApiErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult()
                .getFieldErrors()
                .stream()
                .map(FieldError::getDefaultMessage)
                .collect(Collectors.joining("; "));

        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ApiErrorResponse(ErrorCode.VALIDATION_FAILED.name(), message, LocalDateTime.now()));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ApiErrorResponse> handleGeneric(Exception ex) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new ApiErrorResponse(ErrorCode.PROCESSING_ERROR.name(), ex.getMessage(), LocalDateTime.now()));
    }
}

package org.example.payment.model;

import java.math.BigDecimal;
import java.time.LocalDateTime;

public class Payment {
    private String id;
    private String idempotencyKey;
    private String sourceAccount;
    private String destinationAccount;
    private String reference;
    private BigDecimal amount;
    private String currency;
    private PaymentStatus status;
    private String errorCode;
    private String errorMessage;
    private LocalDateTime createdAt;
    private LocalDateTime updatedAt;

    public String getId() {
        return id;
    }

    public void setId(String id) {
        this.id = id;
    }

    public String getIdempotencyKey() {
        return idempotencyKey;
    }

    public void setIdempotencyKey(String idempotencyKey) {
        this.idempotencyKey = idempotencyKey;
    }

    public String getSourceAccount() {
        return sourceAccount;
    }

    public void setSourceAccount(String sourceAccount) {
        this.sourceAccount = sourceAccount;
    }

    public String getDestinationAccount() {
        return destinationAccount;
    }

    public void setDestinationAccount(String destinationAccount) {
        this.destinationAccount = destinationAccount;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public String getReference() {
        return reference;
    }

    public void setReference(String reference) {
        this.reference = reference;
    }

    public String getCurrency() {
        return currency;
    }

    public void setCurrency(String currency) {
        this.currency = currency;
    }

    public PaymentStatus getStatus() {
        return status;
    }

    public void setStatus(PaymentStatus status) {
        this.status = status;
    }

    public String getErrorCode() {
        return errorCode;
    }

    public void setErrorCode(String errorCode) {
        this.errorCode = errorCode;
    }

    public String getErrorMessage() {
        return errorMessage;
    }

    public void setErrorMessage(String errorMessage) {
        this.errorMessage = errorMessage;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(LocalDateTime updatedAt) {
        this.updatedAt = updatedAt;
    }
}

package org.example.payment.model;

public enum PaymentStatus {
    CREATED,
    VALIDATED,
    SENT,
    COMPLETED,
    FAILED
}

package org.example.payment.model;

import java.time.LocalDateTime;

public class PaymentStatusHistory {
    private Long id;
    private String paymentId;
    private PaymentStatus fromStatus;
    private PaymentStatus toStatus;
    private String errorCode;
    private String errorMessage;
    private String triggeredBy;
    private LocalDateTime changedAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getPaymentId() {
        return paymentId;
    }

    public void setPaymentId(String paymentId) {
        this.paymentId = paymentId;
    }

    public PaymentStatus getFromStatus() {
        return fromStatus;
    }

    public void setFromStatus(PaymentStatus fromStatus) {
        this.fromStatus = fromStatus;
    }

    public PaymentStatus getToStatus() {
        return toStatus;
    }

    public void setToStatus(PaymentStatus toStatus) {
        this.toStatus = toStatus;
    }

    public String getErrorCode() {
        return errorCode;
    }

    public void setErrorCode(String errorCode) {
        this.errorCode = errorCode;
    }

    public String getErrorMessage() {
        return errorMessage;
    }

    public void setErrorMessage(String errorMessage) {
        this.errorMessage = errorMessage;
    }

    public String getTriggeredBy() {
        return triggeredBy;
    }

    public void setTriggeredBy(String triggeredBy) {
        this.triggeredBy = triggeredBy;
    }

    public LocalDateTime getChangedAt() {
        return changedAt;
    }

    public void setChangedAt(LocalDateTime changedAt) {
        this.changedAt = changedAt;
    }
}

package org.example.payment.repository;

import org.example.payment.model.Payment;
import org.example.payment.model.PaymentStatus;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

@Repository
public class PaymentRepository {

    private final NamedParameterJdbcTemplate jdbcTemplate;

    public PaymentRepository(NamedParameterJdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public void insert(Payment payment) {
        String sql = """
                INSERT INTO payments (
                    id, idempotency_key, source_account, destination_account, reference, amount,
                    currency, status, error_code, error_message, created_at, updated_at
                ) VALUES (
                    :id, :idempotencyKey, :sourceAccount, :destinationAccount, :reference, :amount,
                    :currency, :status, :errorCode, :errorMessage, :createdAt, :updatedAt
                )
                """;

        MapSqlParameterSource params = new MapSqlParameterSource()
                .addValue("id", payment.getId())
                .addValue("idempotencyKey", payment.getIdempotencyKey())
                .addValue("sourceAccount", payment.getSourceAccount())
                .addValue("destinationAccount", payment.getDestinationAccount())
                .addValue("reference", payment.getReference())
                .addValue("amount", payment.getAmount())
                .addValue("currency", payment.getCurrency())
                .addValue("status", payment.getStatus().name())
                .addValue("errorCode", payment.getErrorCode())
                .addValue("errorMessage", payment.getErrorMessage())
                .addValue("createdAt", payment.getCreatedAt())
                .addValue("updatedAt", payment.getUpdatedAt());

        jdbcTemplate.update(sql, params);
    }

    public void update(Payment payment) {
        String sql = """
                UPDATE payments
                SET status = :status,
                    error_code = :errorCode,
                    error_message = :errorMessage,
                    updated_at = :updatedAt
                WHERE id = :id
                """;

        MapSqlParameterSource params = new MapSqlParameterSource()
                .addValue("id", payment.getId())
                .addValue("status", payment.getStatus().name())
                .addValue("errorCode", payment.getErrorCode())
                .addValue("errorMessage", payment.getErrorMessage())
                .addValue("updatedAt", payment.getUpdatedAt());

        jdbcTemplate.update(sql, params);
    }

    public Optional<Payment> findById(String id) {
        String sql = "SELECT * FROM payments WHERE id = :id";
        List<Payment> result = jdbcTemplate.query(sql, new MapSqlParameterSource("id", id), new PaymentRowMapper());
        return result.stream().findFirst();
    }

    public Optional<Payment> findByIdempotencyKey(String idempotencyKey) {
        String sql = "SELECT * FROM payments WHERE idempotency_key = :idempotencyKey";
        List<Payment> result = jdbcTemplate.query(sql, new MapSqlParameterSource("idempotencyKey", idempotencyKey), new PaymentRowMapper());
        return result.stream().findFirst();
    }

    public List<Payment> findAll() {
        return jdbcTemplate.query("SELECT * FROM payments ORDER BY created_at DESC", new PaymentRowMapper());
    }

    public List<Payment> findByStatus(PaymentStatus status) {
        String sql = "SELECT * FROM payments WHERE status = :status ORDER BY created_at DESC";
        return jdbcTemplate.query(sql, new MapSqlParameterSource("status", status.name()), new PaymentRowMapper());
    }

    private static class PaymentRowMapper implements RowMapper<Payment> {
        @Override
        public Payment mapRow(ResultSet rs, int rowNum) throws SQLException {
            Payment payment = new Payment();
            payment.setId(rs.getString("id"));
            payment.setIdempotencyKey(rs.getString("idempotency_key"));
            payment.setSourceAccount(rs.getString("source_account"));
            payment.setDestinationAccount(rs.getString("destination_account"));
            payment.setReference(rs.getString("reference"));
            payment.setAmount(rs.getBigDecimal("amount"));
            payment.setCurrency(rs.getString("currency"));
            payment.setStatus(PaymentStatus.valueOf(rs.getString("status")));
            payment.setErrorCode(rs.getString("error_code"));
            payment.setErrorMessage(rs.getString("error_message"));
            payment.setCreatedAt(rs.getTimestamp("created_at").toLocalDateTime());
            payment.setUpdatedAt(rs.getTimestamp("updated_at").toLocalDateTime());
            return payment;
        }
    }
}

package org.example.payment.repository;

import org.example.payment.model.PaymentStatus;
import org.example.payment.model.PaymentStatusHistory;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.core.namedparam.MapSqlParameterSource;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Repository;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;

@Repository
public class PaymentStatusHistoryRepository {

    private final NamedParameterJdbcTemplate jdbcTemplate;

    public PaymentStatusHistoryRepository(NamedParameterJdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    public void insert(PaymentStatusHistory history) {
        String sql = """
                INSERT INTO payment_status_history (
                    payment_id, from_status, to_status, error_code,
                    error_message, triggered_by, changed_at
                ) VALUES (
                    :paymentId, :fromStatus, :toStatus, :errorCode,
                    :errorMessage, :triggeredBy, :changedAt
                )
                """;

        MapSqlParameterSource params = new MapSqlParameterSource()
                .addValue("paymentId", history.getPaymentId())
                .addValue("fromStatus", history.getFromStatus() == null ? null : history.getFromStatus().name())
                .addValue("toStatus", history.getToStatus().name())
                .addValue("errorCode", history.getErrorCode())
                .addValue("errorMessage", history.getErrorMessage())
                .addValue("triggeredBy", history.getTriggeredBy())
                .addValue("changedAt", history.getChangedAt());

        jdbcTemplate.update(sql, params);
    }

    public List<PaymentStatusHistory> findByPaymentId(String paymentId) {
        String sql = "SELECT * FROM payment_status_history WHERE payment_id = :paymentId ORDER BY changed_at ASC";
        return jdbcTemplate.query(sql, new MapSqlParameterSource("paymentId", paymentId), new PaymentStatusHistoryRowMapper());
    }

    private static class PaymentStatusHistoryRowMapper implements RowMapper<PaymentStatusHistory> {
        @Override
        public PaymentStatusHistory mapRow(ResultSet rs, int rowNum) throws SQLException {
            PaymentStatusHistory history = new PaymentStatusHistory();
            history.setId(rs.getLong("id"));
            history.setPaymentId(rs.getString("payment_id"));
            String fromStatus = rs.getString("from_status");
            history.setFromStatus(fromStatus == null ? null : PaymentStatus.valueOf(fromStatus));
            history.setToStatus(PaymentStatus.valueOf(rs.getString("to_status")));
            history.setErrorCode(rs.getString("error_code"));
            history.setErrorMessage(rs.getString("error_message"));
            history.setTriggeredBy(rs.getString("triggered_by"));
            history.setChangedAt(rs.getTimestamp("changed_at").toLocalDateTime());
            return history;
        }
    }
}

package org.example.payment.service;

import org.example.payment.dto.CreatePaymentRequest;
import org.example.payment.dto.FailPaymentRequest;
import org.example.payment.exception.BusinessException;
import org.example.payment.exception.ErrorCode;
import org.example.payment.model.Payment;
import org.example.payment.model.PaymentStatus;
import org.example.payment.model.PaymentStatusHistory;
import org.example.payment.repository.PaymentRepository;
import org.example.payment.repository.PaymentStatusHistoryRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.Set;
import java.util.UUID;

@Service
public class PaymentService {

    private static final Set<String> SUPPORTED_CURRENCIES = Set.of("USD", "EUR", "GBP");

    private final PaymentRepository paymentRepository;
    private final PaymentStatusHistoryRepository historyRepository;
    private final PaymentStateMachine stateMachine;

    public PaymentService(
            PaymentRepository paymentRepository,
            PaymentStatusHistoryRepository historyRepository,
            PaymentStateMachine stateMachine
    ) {
        this.paymentRepository = paymentRepository;
        this.historyRepository = historyRepository;
        this.stateMachine = stateMachine;
    }

    @Transactional
    public CreatePaymentResult createPayment(CreatePaymentRequest request) {
        validateCreateRequest(request);

        return paymentRepository.findByIdempotencyKey(request.idempotencyKey())
                .map(existing -> new CreatePaymentResult(existing, false))
                .orElseGet(() -> {
                    Payment payment = new Payment();
                    payment.setId(UUID.randomUUID().toString());
                    payment.setIdempotencyKey(request.idempotencyKey());
                    payment.setSourceAccount(request.sourceAccount());
                    payment.setDestinationAccount(request.destinationAccount());
                    payment.setReference(request.reference());
                    payment.setAmount(request.amount());
                    payment.setCurrency(request.currency());
                    payment.setStatus(PaymentStatus.CREATED);
                    payment.setCreatedAt(LocalDateTime.now());
                    payment.setUpdatedAt(payment.getCreatedAt());

                    paymentRepository.insert(payment);
                    addHistory(payment.getId(), null, PaymentStatus.CREATED, null, null, "API");

                    return new CreatePaymentResult(payment, true);
                });
    }

    public Payment getPayment(String paymentId) {
        return paymentRepository.findById(paymentId)
                .orElseThrow(() -> new BusinessException(ErrorCode.PAYMENT_NOT_FOUND, "Payment not found: " + paymentId));
    }

    public List<Payment> listPayments(PaymentStatus status) {
        if (status == null) {
            return paymentRepository.findAll();
        }
        return paymentRepository.findByStatus(status);
    }

    public List<PaymentStatusHistory> getHistory(String paymentId) {
        getPayment(paymentId);
        return historyRepository.findByPaymentId(paymentId);
    }

    @Transactional
    public Payment validate(String paymentId) {
        return transition(paymentId, PaymentStatus.VALIDATED, null, null, "API_VALIDATE");
    }

    @Transactional
    public Payment send(String paymentId) {
        return transition(paymentId, PaymentStatus.SENT, null, null, "API_SEND");
    }

    @Transactional
    public Payment complete(String paymentId) {
        return transition(paymentId, PaymentStatus.COMPLETED, null, null, "API_COMPLETE");
    }

    @Transactional
    public Payment fail(String paymentId, FailPaymentRequest request) {
        return transition(paymentId, PaymentStatus.FAILED, request.errorCode(), request.errorMessage(), "API_FAIL");
    }

    private void validateCreateRequest(CreatePaymentRequest request) {
        if (request.sourceAccount().equals(request.destinationAccount())) {
            throw new BusinessException(ErrorCode.INVALID_ACCOUNT, "sourceAccount and destinationAccount must be different");
        }
        if (!SUPPORTED_CURRENCIES.contains(request.currency())) {
            throw new BusinessException(ErrorCode.INVALID_CURRENCY, "Unsupported currency: " + request.currency());
        }
    }

    private Payment transition(
            String paymentId,
            PaymentStatus targetStatus,
            String errorCode,
            String errorMessage,
            String triggeredBy
    ) {
        Payment payment = getPayment(paymentId);
        stateMachine.assertCanTransition(payment.getStatus(), targetStatus);

        PaymentStatus fromStatus = payment.getStatus();
        payment.setStatus(targetStatus);
        payment.setErrorCode(errorCode);
        payment.setErrorMessage(errorMessage);
        payment.setUpdatedAt(LocalDateTime.now());
        paymentRepository.update(payment);

        addHistory(payment.getId(), fromStatus, targetStatus, errorCode, errorMessage, triggeredBy);
        return payment;
    }

    private void addHistory(
            String paymentId,
            PaymentStatus from,
            PaymentStatus to,
            String errorCode,
            String errorMessage,
            String triggeredBy
    ) {
        PaymentStatusHistory history = new PaymentStatusHistory();
        history.setPaymentId(paymentId);
        history.setFromStatus(from);
        history.setToStatus(to);
        history.setErrorCode(errorCode);
        history.setErrorMessage(errorMessage);
        history.setTriggeredBy(triggeredBy);
        history.setChangedAt(LocalDateTime.now());
        historyRepository.insert(history);
    }

    public record CreatePaymentResult(Payment payment, boolean created) {
    }
}

package org.example.payment.service;

import org.example.payment.exception.BusinessException;
import org.example.payment.exception.ErrorCode;
import org.example.payment.model.PaymentStatus;
import org.springframework.stereotype.Component;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

@Component
public class PaymentStateMachine {

    private final Map<PaymentStatus, Set<PaymentStatus>> transitions = new EnumMap<>(PaymentStatus.class);

    public PaymentStateMachine() {
        transitions.put(PaymentStatus.CREATED, EnumSet.of(PaymentStatus.VALIDATED, PaymentStatus.FAILED));
        transitions.put(PaymentStatus.VALIDATED, EnumSet.of(PaymentStatus.SENT, PaymentStatus.FAILED));
        transitions.put(PaymentStatus.SENT, EnumSet.of(PaymentStatus.COMPLETED, PaymentStatus.FAILED));
        transitions.put(PaymentStatus.COMPLETED, EnumSet.noneOf(PaymentStatus.class));
        transitions.put(PaymentStatus.FAILED, EnumSet.noneOf(PaymentStatus.class));
    }

    public void assertCanTransition(PaymentStatus from, PaymentStatus to) {
        Set<PaymentStatus> allowed = transitions.getOrDefault(from, EnumSet.noneOf(PaymentStatus.class));
        if (!allowed.contains(to)) {
            throw new BusinessException(
                    ErrorCode.INVALID_STATUS_TRANSITION,
                    "Invalid status transition: " + from + " -> " + to
            );
        }
    }
}

CREATE TABLE IF NOT EXISTS payments ( id VARCHAR(64) PRIMARY KEY, idempotency_key VARCHAR(64) NOT NULL UNIQUE, source_account VARCHAR(20) NOT NULL, destination_account VARCHAR(20) NOT NULL, reference VARCHAR(140), amount DECIMAL(14, 2) NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, error_code VARCHAR(64), error_message VARCHAR(255), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL );
CREATE TABLE IF NOT EXISTS payment_status_history ( id BIGINT AUTO_INCREMENT PRIMARY KEY, payment_id VARCHAR(64) NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, error_code VARCHAR(64), error_message VARCHAR(255), triggered_by VARCHAR(64) NOT NULL, changed_at TIMESTAMP NOT NULL, CONSTRAINT fk_history_payment FOREIGN KEY (payment_id) REFERENCES payments(id) );
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status); CREATE INDEX IF NOT EXISTS idx_history_payment_id ON payment_status_history(payment_id);

CREATE TABLE IF NOT EXISTS payments ( id VARCHAR(64) PRIMARY KEY, idempotency_key VARCHAR(64) NOT NULL UNIQUE, source_account VARCHAR(20) NOT NULL, destination_account VARCHAR(20) NOT NULL, reference VARCHAR(140), amount DECIMAL(14, 2) NOT NULL, currency VARCHAR(3) NOT NULL, status VARCHAR(20) NOT NULL, error_code VARCHAR(64), error_message VARCHAR(255), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL );
CREATE TABLE IF NOT EXISTS payment_status_history ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payment_id VARCHAR(64) NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, error_code VARCHAR(64), error_message VARCHAR(255), triggered_by VARCHAR(64) NOT NULL, changed_at TIMESTAMP NOT NULL, CONSTRAINT fk_history_payment FOREIGN KEY (payment_id) REFERENCES payments(id) );
CREATE INDEX IF NOT EXISTS idx_payments_status ON payments(status); CREATE INDEX IF NOT EXISTS idx_history_payment_id ON payment_status_history(payment_id);

package org.example.payment;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class PaymentApiIntegrationTest {

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Test
    void paymentLifecycleAndIdempotencyShouldWork() throws Exception {
        String createBody = """
                {
                  "idempotencyKey": "itest-001",
                  "sourceAccount": "12345678",
                  "destinationAccount": "87654321",
                  "amount": 100.00,
                  "currency": "USD",
                  "reference": "integration-test"
                }
                """;

        String createdJson = mockMvc.perform(post("/api/payments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(createBody))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();

        JsonNode createdNode = objectMapper.readTree(createdJson);
        String paymentId = createdNode.get("id").asText();

        mockMvc.perform(post("/api/payments/{id}/validate", paymentId))
                .andExpect(status().isOk());
        mockMvc.perform(post("/api/payments/{id}/send", paymentId))
                .andExpect(status().isOk());
        String completedJson = mockMvc.perform(post("/api/payments/{id}/complete", paymentId))
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();

        JsonNode completedNode = objectMapper.readTree(completedJson);
        assertThat(completedNode.get("status").asText()).isEqualTo("COMPLETED");

        String secondCreateJson = mockMvc.perform(post("/api/payments")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(createBody))
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();

        JsonNode secondCreateNode = objectMapper.readTree(secondCreateJson);
        assertThat(secondCreateNode.get("id").asText()).isEqualTo(paymentId);

        String historyJson = mockMvc.perform(get("/api/payments/{id}/history", paymentId))
                .andExpect(status().isOk())
                .andReturn().getResponse().getContentAsString();

        JsonNode history = objectMapper.readTree(historyJson);
        assertThat(history).hasSize(4);
    }
}
